import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Bzd4OF_4.js";const p=JSON.parse('{"title":"Finance integrity","description":"","frontmatter":{},"headers":[],"relativePath":"finance-integrity.md","filePath":"finance-integrity.md"}'),r={name:"finance-integrity.md"};function o(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="finance-integrity" tabindex="-1">Finance integrity <a class="header-anchor" href="#finance-integrity" aria-label="Permalink to &quot;Finance integrity&quot;">​</a></h1><p>Financial correctness is TALLY’s primary architecture driver.</p><ul><li>Money uses exact decimal representations; binary floating point is not suitable for financial amounts.</li><li>Posted or otherwise established financial facts are immutable.</li><li>Corrections use explicit reversal, adjustment, amendment, return, unapplication, replacement, or compensation flows.</li><li>Retriable state-changing commands require scoped idempotency.</li><li>Integration events use a transactional outbox so database state and publication intent are durable together.</li><li>Material state changes require authorization and audit evidence.</li><li>Accounting ownership stays inside the bounded context that owns the fact.</li></ul><p>The <a href="https://github.com/toanle88/Tally/blob/main/docs/specs/finance_domain_model_ddd.md" target="_blank" rel="noreferrer">DDD baseline</a> is authoritative for domain language and invariants.</p>',4)])])}const f=t(r,[["render",o]]);export{p as __pageData,f as default};
